create function touch_updated() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create table services(id uuid primary key default gen_random_uuid(),name text not null unique,owner text not null check(length(trim(owner))>0),criticality text not null check(criticality in ('critical','standard')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table incidents(id uuid primary key default gen_random_uuid(),reference text not null unique,name text not null,service_id uuid references services(id),owner text, severity text not null default 'unclassified' check(severity in ('unclassified','sev1','sev2','sev3')),state text not null default 'unverified' check(state in ('unverified','open','resolved','reviewed','closed')),summary text not null default '',started_at timestamptz not null,resolved_at timestamptz,review_due date,retention_review date,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(resolved_at is null or resolved_at>=started_at),check(state in ('unverified','open') or resolved_at is not null),check(state='unverified' or (service_id is not null and owner is not null and length(trim(owner))>0 and severity<>'unclassified' and review_due is not null and retention_review is not null)));
create table timeline(id uuid primary key default gen_random_uuid(),incident_id uuid not null references incidents(id),happened_at timestamptz not null,note text not null,evidence text not null,actor text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table actions(id uuid primary key default gen_random_uuid(),incident_id uuid not null references incidents(id),name text not null,owner text not null,due_on date not null,state text not null default 'open' check(state in ('open','done')),completed_at timestamptz,evidence text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(state<>'done' or (completed_at is not null and evidence is not null and length(trim(evidence))>0)));
create table reviews(id uuid primary key default gen_random_uuid(),incident_id uuid not null unique references incidents(id),reviewer text not null,reviewed_at timestamptz not null,cause text not null,lessons text not null,evidence text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table source_rows(id uuid primary key default gen_random_uuid(),namespace text not null,source_key text not null,incident_id uuid not null unique references incidents(id),raw jsonb not null,mapped jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(namespace,source_key));
create table audit_events(id uuid primary key default gen_random_uuid(),command text not null,actor text not null,details jsonb not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create function deny_change() returns trigger language plpgsql as $$ begin raise exception 'Append-only record'; end $$;
create trigger audit_immutable before update or delete on audit_events for each row execute function deny_change();
create trigger timeline_immutable before update or delete on timeline for each row execute function deny_change();
create trigger source_immutable before update or delete on source_rows for each row execute function deny_change();
do $$ declare t text; begin foreach t in array array['services','incidents','actions','reviews'] loop execute format('create trigger touch before update on %I for each row execute function touch_updated()',t); end loop; foreach t in array array['services','incidents','timeline','actions','reviews','source_rows','audit_events'] loop execute format('alter table %I enable row level security',t);execute format('revoke all on %I from public',t);end loop;end $$;
create view v_review_queue with(security_invoker=true) as select i.id,i.reference,i.name,s.name service,i.owner,i.severity,i.state,i.review_due,current_date-i.review_due days_overdue,(select count(*)::int from actions a where a.incident_id=i.id and a.state='open') open_actions from incidents i left join services s on s.id=i.service_id where i.state<>'closed';
create view v_action_queue with(security_invoker=true) as select a.id,i.reference,s.name service,a.name action,a.owner,a.due_on,current_date-a.due_on days_overdue,i.severity from actions a join incidents i on i.id=a.incident_id left join services s on s.id=i.service_id where a.state='open';
create view v_service_health with(security_invoker=true) as select s.id,s.name service,s.owner,s.criticality,count(i.id)::int incidents,count(i.id) filter(where i.state<>'closed')::int unfinished,count(i.id) filter(where i.started_at>=now()-interval '30 days')::int last_30_days,round(avg(extract(epoch from(i.resolved_at-i.started_at))/60)::numeric,1) avg_minutes_to_resolution,(select count(*)::int from actions a join incidents j on j.id=a.incident_id where j.service_id=s.id and a.state='open' and a.due_on<current_date) overdue_actions from services s left join incidents i on i.service_id=s.id group by s.id;
create view v_compliance with(security_invoker=true) as
 select reference,'classification' rule,'Verify service, severity, owner and review dates' finding from incidents where state='unverified'
 union all select reference,'timeline','Record chronology and evidence' from incidents i where state<>'unverified' and not exists(select 1 from timeline t where t.incident_id=i.id)
 union all select reference,'review_due','Review deadline passed without a review' from incidents i where state in ('open','resolved') and review_due<current_date and not exists(select 1 from reviews r where r.incident_id=i.id)
 union all select reference,'retention','Review the purpose and retention of this record' from incidents where retention_review<current_date
 union all select i.reference,'action_due','Overdue action: '||a.name from actions a join incidents i on i.id=a.incident_id where a.state='open' and a.due_on<current_date;
revoke all on v_review_queue,v_action_queue,v_service_health,v_compliance from public;
